// Guards on `docs/index.html`, the bilingual landing page.
//
// The page is one hand-written HTML file. English lives in the markup; Japanese lives
// in `window.__JA`, keyed by each element's `data-t` (and `data-t-aria` / `data-t-alt`
// for attributes), and the toggle swaps them. Some text is generated by script (the
// simulation results, the request walkthrough, the diagrams, the price bars). These
// checks are the ones that are silent when broken:
//
//   - A key with no Japanese entry, or English text with no key at all, keeps
//     rendering English to a Japanese reader. Names and identifiers that stay as
//     they are carry `translate="no"`.
//   - Script-generated text has to follow the toggle both ways, not only the markup.
//   - The page promises no network request (it is a static file), and every image
//     it loads must exist next to it.
//   - No emoji, the bar the repository holds elsewhere.
//   - No horizontal scroll on a phone, with every collapsible open.
//
// Loaded over `file://` from a path relative to this spec, because the page is a
// static artifact rather than something the dev server serves.
import { expect, test, type Page } from '@playwright/test'
import { existsSync, readFileSync } from 'node:fs'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { resolve } from 'node:path'

// Playwright runs with the frontend package as its working directory.
const DOCS = resolve(process.cwd(), '..', 'docs')
const PAGE = pathToFileURL(resolve(DOCS, 'index.html')).href
const DOCS_URL = pathToFileURL(DOCS).href + '/'
// Japanese entries that are names and stay as they are.
const JA_NAMES = new Set(['hero.v.bedrock', 'vs.eyebrow'])
// Kana, kanji and Japanese punctuation.
const JAPANESE = /[\u3000-\u30ff\u4e00-\u9fff]/

async function open(page: Page, lang: 'en' | 'ja') {
  await page.goto(`${PAGE}?lang=${lang}`)
  await expect(page.locator('html')).toHaveAttribute('lang', lang)
}

async function openEverything(page: Page) {
  await page.evaluate(async () => {
    document.querySelectorAll('details').forEach((d) => (d.open = true))
    for (let y = 0; y < document.body.scrollHeight; y += 600) {
      window.scrollTo({ top: y, behavior: 'instant' })
      await new Promise((r) => setTimeout(r, 30))
    }
  })
}

test.describe('docs landing page', () => {
  // The walkthrough waits between steps unless motion is reduced.
  test.use({ reducedMotion: 'reduce' })

  test('every translatable key has a Japanese entry', async ({ page }) => {
    await open(page, 'en')
    const { count, jaSize, missing } = await page.evaluate(
      ([names, jp]) => {
        const japanese = new RegExp(jp)
        const ja = (window as unknown as { __JA?: Record<string, unknown> }).__JA
        const keys = new Set<string>()
        for (const el of Array.from(document.querySelectorAll<HTMLElement>('[data-t]')))
          keys.add(el.dataset.t!)
        for (const el of Array.from(document.querySelectorAll<HTMLElement>('[data-t-aria]')))
          keys.add(el.dataset.tAria!)
        for (const el of Array.from(document.querySelectorAll<HTMLElement>('[data-t-alt]')))
          keys.add(el.dataset.tAlt!)
        const has = (k: string) =>
          !!ja &&
          Object.prototype.hasOwnProperty.call(ja, k) &&
          typeof ja[k] === 'string' &&
          (ja[k] as string).trim() !== '' &&
          (names.includes(k) ||
            japanese.test(ja[k] as string) ||
            !/[A-Za-z]{3,}/.test(ja[k] as string))
        return {
          count: keys.size,
          jaSize: ja ? Object.keys(ja).length : 0,
          missing: [...keys].filter((k) => !has(k)).sort(),
        }
      },
      [[...JA_NAMES], JAPANESE.source] as const,
    )
    expect(count, 'no [data-t] elements found; the page structure changed').toBeGreaterThan(0)
    expect(jaSize, 'window.__JA is missing or empty').toBeGreaterThan(0)
    expect(missing, 'these keys have no Japanese entry, or the entry is still English').toEqual([])
  })

  test('no English text without a key on the Japanese page', async ({ page }) => {
    await open(page, 'ja')
    await openEverything(page)
    const english = await page.evaluate(() => {
      const out = new Set<string>()
      const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
      for (let n = walk.nextNode(); n; n = walk.nextNode()) {
        const text = (n.textContent ?? '').trim()
        if (!/[A-Za-z]{4,}/.test(text)) continue
        const el = n.parentElement!
        // SVG labels are built by script through tr(); a key it asks for in Japanese
        // and the bundle lacks is in window.__TR_MISS, checked below.
        if (el.closest('[data-t], [translate="no"], code, pre, svg, script, style, [hidden]'))
          continue
        out.add(`<${el.tagName.toLowerCase()}> ${text.slice(0, 60)}`)
      }
      return [...out]
    })
    expect(english, 'give this text a data-t key, or mark a name translate="no"').toEqual([])
    const misses = await page.evaluate(
      () => (window as unknown as { __TR_MISS?: string[] }).__TR_MISS,
    )
    expect(misses, 'the script asked for these keys in Japanese and the bundle lacks them').toEqual(
      [],
    )
  })

  test('the toggle switches the markup and the script-generated text, both ways', async ({
    page,
  }) => {
    await open(page, 'en')
    const hero = page.locator('.hero h1')
    const result = page.locator('#r-b')
    await expect(hero).toContainText('Amazon Bedrock')
    await expect(result).toContainText('Stopped at')

    await page.locator('.lang button[data-lang="ja"]').click()
    await expect(page.locator('html')).toHaveAttribute('lang', 'ja')
    await expect(hero).toContainText('予算')
    await expect(result).toContainText('止まりました')
    await expect(result).not.toContainText('Stopped at')
    // The price bars are rebuilt by script on a language change.
    const bars = page.locator('#price-bars')
    await expect(bars).toContainText('入力')

    // The request walkthrough is built by script as well.
    await page.locator('#why details.more > summary', { hasText: 'リクエスト' }).first().click()
    await page.locator('#flow-over').click()
    await expect(page.locator('#flow-text')).toContainText('402', { timeout: 10_000 })
    await expect(page.locator('#flow-svg')).toContainText('確保')

    await page.locator('.lang button[data-lang="en"]').click()
    await expect(hero).not.toContainText('予算')
    await expect(result).toContainText('Stopped at')
    await expect(page.locator('#flow-svg')).toContainText('Reserve')
    await expect(page.locator('#flow-svg')).not.toContainText('確保')
    await expect(bars).toContainText('input')
    await expect(bars).not.toContainText('入力')
  })

  for (const lang of ['en', 'ja'] as const) {
    test(`no network request and no missing image (${lang})`, async ({ page }) => {
      const outside: string[] = []
      const failed: string[] = []
      page.on('request', (r) => {
        const u = r.url()
        if (!u.startsWith(DOCS_URL) && !u.startsWith('data:')) outside.push(u)
      })
      page.on('requestfailed', (r) => failed.push(r.url()))
      await open(page, lang)
      await openEverything(page)
      await page.waitForLoadState('networkidle')
      expect(outside, 'requests outside docs/').toEqual([])
      expect(failed, 'requests that failed').toEqual([])
      const images = await page.evaluate(() =>
        Array.from(document.images, (i) => i.src).filter((s) => s.startsWith('file:')),
      )
      expect(images.length).toBeGreaterThan(0)
      expect(images.filter((s) => !existsSync(fileURLToPath(s)))).toEqual([])
    })
  }

  test('every console screenshot the gallery can show exists, in both languages', async ({
    page,
  }) => {
    await open(page, 'en')
    const files = await page.evaluate(() => {
      const shots = (window as unknown as { __SHOTS?: { file: string }[] }).__SHOTS ?? []
      return shots.flatMap((s) => [`${s.file}.en.png`, `${s.file}.ja.png`])
    })
    expect(files.length).toBeGreaterThan(0)
    expect(files.filter((f) => !existsSync(resolve(DOCS, 'screenshots', 'console', f)))).toEqual([])
  })

  test('no emoji anywhere in the file, markup, attributes and script text included', () => {
    const source = readFileSync(resolve(DOCS, 'index.html'), 'utf8')
    // Emoji presentation, not typographic symbols such as arrows or the copyright sign.
    const found = [...new Set(source.match(/\p{Emoji_Presentation}|\u{FE0F}/gu) ?? [])]
    expect(found).toEqual([])
  })

  test.describe('on a phone', () => {
    test.use({ viewport: { width: 390, height: 844 } })
    for (const lang of ['en', 'ja'] as const) {
      test(`no horizontal scroll with everything open (${lang})`, async ({ page }) => {
        await open(page, lang)
        await openEverything(page)
        const overflow = await page.evaluate(
          () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
        )
        expect(overflow, 'the page is wider than the screen').toBeLessThanOrEqual(1)
      })
    }
  })
})
